// Prepara el prompt para Gemini y decodifica el base64
const body = $input.first().json.body || $input.first().json;
const archivo = body.archivo || {};
const meta = body.metadata || {};

let contenidoLegible = '';
try {
  const buff = Buffer.from(archivo.base64 || '', 'base64');
  const esText = /text|json|xml|javascript|typescript|html|css|markdown|csv|sh|sql|python|yaml/i.test(archivo.mimetype || '');
  if (esText) {
    contenidoLegible = buff.toString('utf-8').slice(0, 80_000); // limite 80KB
  } else {
    contenidoLegible = `(Archivo binario de ${buff.length} bytes - nombre: ${archivo.nombre})`;
  }
} catch (e) {
  contenidoLegible = '(No se pudo decodificar el archivo)';
}

const prompt = `Eres un revisor de seguridad de un marketplace de scripts y plugins llamado ScriptBay.
Tu tarea es decidir si el siguiente archivo contiene codigo o contenido MALICIOSO.
Responde EXCLUSIVAMENTE con un JSON valido con esta forma exacta:
{"aprobado": true|false, "motivo": "<motivo corto>", "detalle": "<explicacion 1-2 frases>", "score": <0-100 donde 100 es totalmente seguro>}

No añadas texto fuera del JSON. No uses markdown.

Metadata del producto:
- Titulo: ${meta.titulo || '-'}
- Tipo: ${meta.tipo || '-'}
- Descripcion: ${meta.descripcion || '-'}
- Categoria: ${meta.categoria || '-'}

Archivo:
- Nombre: ${archivo.nombre}
- Mimetype: ${archivo.mimetype}

Contenido (puede estar truncado):
---
${contenidoLegible}
---`;

return [{ json: { prompt, meta, archivo: { nombre: archivo.nombre, mimetype: archivo.mimetype } } }];

// Extrae el JSON que devuelve Gemini
const resp = $input.first().json;
let textoIa = '';
try {
  textoIa = resp.candidates[0].content.parts[0].text;
} catch (e) {
  return [{ json: { aprobado: false, motivo: 'gemini-sin-respuesta', detalle: JSON.stringify(resp).slice(0,300) } }];
}

try {
  const parsed = JSON.parse(textoIa);
  return [{ json: {
    aprobado: Boolean(parsed.aprobado),
    motivo: parsed.motivo || (parsed.aprobado ? 'ok' : 'rechazado'),
    detalle: parsed.detalle || '',
    score: parsed.score ?? null
  }}];
} catch (err) {
  return [{ json: { aprobado: false, motivo: 'json-invalido', detalle: textoIa.slice(0, 300) } }];
}
